"""
This module decodes an embedded JPEG image from base64 data, verifies its integrity
using SHA-256, and writes it to an output file.
"""
import os
import base64
import hashlib
import sys

# Expected SHA-256 hash of art.jpg
EXPECTED_HASH = "9d902138bcf19323420d753c87137f3d52943b309cdddb89a7001506e0e3d0ca"
IMAGE_DATA = ""

def main():
    try:
        data = base64.b64decode(IMAGE_DATA)
    except Exception as e:
        print(f"Error decoding image data: {e}")
        sys.exit(1)

    # Check JPEG magic bytes and end marker
    # JPEG Start: FF D8 FF
    # JPEG End: FF D9
    if not (data.startswith(b'\xff\xd8\xff') and data.endswith(b'\xff\xd9')):
        print("Invalid JPEG format.")
        sys.exit(1)

    # Calculate hash
    actual_hash = hashlib.sha256(data).hexdigest()
    if actual_hash != EXPECTED_HASH:
        print(f"Hash mismatch! Expected {EXPECTED_HASH}, got {actual_hash}")
        sys.exit(1)

    # Get output directory
    output_dir = os.environ.get("MAKEFUN_OUTPUT_DIR", "/output")
    os.makedirs(output_dir, exist_ok=True)
    
    output_path = os.path.join(output_dir, "entry.png")
    
    # Write file
    with open(output_path, "wb") as f:
        f.write(data)
    
    # Re-read and check
    with open(output_path, "rb") as f:
        written_data = f.read()
        
    written_hash = hashlib.sha256(written_data).hexdigest()
    if written_hash != actual_hash:
        print("Written file hash mismatch!")
        sys.exit(1)
        
    print(f"SUCCESS: Successfully wrote image to {output_path}.\nFile size: {len(written_data)} bytes.\nSHA-256 hash: {written_hash}")

if __name__ == "__main__":
    main()
